:root {
  /* OKLCH Colors */
  --bg-primary: oklch(18% 0.02 265);      /* Deep navy/charcoal (#0d1117 approx) */
  --bg-secondary: oklch(22% 0.02 265);    /* Slightly lighter for cards */
  --bg-tertiary: oklch(28% 0.02 265);     /* Borders and hovers */

  --brand-primary: oklch(0% 0 0);         /* Brand Primary - from brief (#000000) */
  --brand-accent: oklch(75% 0.15 190);    /* Electric Cyan for CTAs */
  --brand-link: oklch(45% 0.10 250);      /* Accent blue #475F91 */

  --text-primary: oklch(95% 0.01 265);    /* Near white */
  --text-secondary: oklch(75% 0.02 265);  /* Muted text */
  --text-tertiary: oklch(60% 0.02 265);   /* Very muted text */

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 1rem;
  --space-4: 1.5rem;
  --space-5: 2rem;
  --space-6: 3rem;
  --space-8: 4rem;
  --space-12: 6rem;
  --space-16: 8rem;

  /* Layout */
  --max-width: 1200px;
  --header-height: 64px;
  --sidebar-width: 260px;

  /* Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
}

/* Light mode overrides (optional, but keep it just in case, though dark-mode first) */
:root[data-theme="light"] {
  --bg-primary: oklch(98% 0.01 265);
  --bg-secondary: oklch(100% 0 0);
  --bg-tertiary: oklch(90% 0.02 265);

  --text-primary: oklch(18% 0.02 265);
  --text-secondary: oklch(35% 0.02 265);
  --text-tertiary: oklch(50% 0.02 265);
}

/* Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--brand-accent);
  text-decoration: none;
  transition: opacity 0.2s;
}

a:hover {
  opacity: 0.8;
}

h1, h2, h3, h4, h5, h6 {
  color: var(--text-primary);
  font-weight: 600;
  line-height: 1.2;
}

h1 { font-size: 3rem; letter-spacing: -0.02em; margin-bottom: var(--space-4); }
h2 { font-size: 2rem; letter-spacing: -0.01em; margin-bottom: var(--space-4); margin-top: var(--space-8); }
h3 { font-size: 1.5rem; margin-bottom: var(--space-3); margin-top: var(--space-6); }

p {
  color: var(--text-secondary);
  margin-bottom: var(--space-4);
  font-size: 1.125rem;
}

ul, ol {
  margin-bottom: var(--space-4);
  padding-left: var(--space-4);
  color: var(--text-secondary);
}

li {
  margin-bottom: var(--space-2);
}

/* Layout Utilities */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.grid {
  display: grid;
  gap: var(--space-6);
}

.grid-2 { grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); }
.grid-3 { grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); }

/* Header */
.header {
  height: var(--header-height);
  border-bottom: 1px solid var(--bg-tertiary);
  display: flex;
  align-items: center;
  position: sticky;
  top: 0;
  background-color: color-mix(in srgb, var(--bg-primary) 90%, transparent);
  backdrop-filter: blur(12px);
  z-index: 100;
}

.header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--text-primary);
  text-decoration: none;
}

.nav-links {
  display: flex;
  gap: var(--space-4);
  align-items: center;
}

.nav-links a {
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 0.95rem;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
}

.nav-utils {
  display: flex;
  gap: var(--space-3);
  align-items: center;
}

.nav-utils button {
  background: none;
  border: 1px solid var(--bg-tertiary);
  color: var(--text-secondary);
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 0.875rem;
}

/* Page Layouts */
.docs-layout {
  display: flex;
  min-height: calc(100vh - var(--header-height));
}

.sidebar {
  width: var(--sidebar-width);
  border-right: 1px solid var(--bg-tertiary);
  padding: var(--space-6) var(--space-4);
  transition: width 0.3s ease, padding 0.3s ease, opacity 0.3s ease;
  overflow-y: auto;
  position: sticky;
  top: var(--header-height);
  height: calc(100vh - var(--header-height));
  flex-shrink: 0;
}

.sidebar.collapsed {
  width: 0;
  padding: 0;
  opacity: 0;
  overflow: hidden;
  border-right: none;
}

.sidebar h4 {
  text-transform: uppercase;
  font-size: 0.75rem;
  letter-spacing: 0.05em;
  color: var(--text-tertiary);
  margin-bottom: var(--space-3);
  margin-top: var(--space-4);
}

.sidebar ul {
  list-style: none;
  padding-left: 0;
}

.sidebar a {
  display: block;
  padding: var(--space-1) 0;
  color: var(--text-secondary);
  font-size: 0.95rem;
}

.sidebar a:hover {
  color: var(--brand-accent);
}

.main-content {
  flex: 1;
  padding: var(--space-8) var(--space-6);
  min-width: 0;
}

.content-header {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-bottom: var(--space-4);
}

.collapse-btn {
  background: var(--bg-secondary);
  border: 1px solid var(--bg-tertiary);
  color: var(--text-primary);
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
}

/* Sections */
.section {
  padding: var(--space-12) 0;
}

.hero {
  padding: var(--space-16) 0 var(--space-8) 0;
  text-align: left;
}

.hero h1 {
  font-size: 4rem;
  max-width: 800px;
}

.hero p {
  font-size: 1.25rem;
  max-width: 700px;
  margin-bottom: var(--space-6);
}

.hero-actions {
  display: flex;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-md);
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  text-decoration: none;
  border: none;
}

.btn-primary {
  background-color: var(--brand-accent);
  color: var(--bg-primary);
}

.btn-primary:hover {
  background-color: color-mix(in srgb, var(--brand-accent) 80%, white);
  opacity: 1;
}

.btn-secondary {
  background-color: transparent;
  color: var(--text-primary);
  border: 1px solid var(--bg-tertiary);
}

.btn-secondary:hover {
  background-color: var(--bg-secondary);
  border-color: var(--text-secondary);
}

/* Cards */
.card {
  background-color: var(--bg-secondary);
  border: 1px solid var(--bg-tertiary);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  transition: transform 0.2s, border-color 0.2s;
  display: flex;
  flex-direction: column;
}

.card:hover {
  transform: translateY(-2px);
  border-color: var(--brand-accent);
}

.card h3 {
  margin-top: 0;
  font-size: 1.25rem;
}

.card p {
  flex-grow: 1;
  font-size: 1rem;
  margin-bottom: var(--space-4);
}

.card .card-cta {
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
}

/* CLI Setup Section */
.cli-setup {
  background-color: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--bg-tertiary);
  overflow: hidden;
}

.cli-accordions {
  display: flex;
  border-bottom: 1px solid var(--bg-tertiary);
}

.accordion-tab {
  flex: 1;
  padding: var(--space-4);
  background: transparent;
  border: none;
  border-right: 1px solid var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
}

.accordion-tab:last-child {
  border-right: none;
}

.accordion-tab.active {
  background-color: var(--bg-primary);
  color: var(--text-primary);
  border-bottom: 2px solid var(--brand-accent);
}

.cli-content {
  padding: var(--space-6);
  display: none;
}

.cli-content.active {
  display: block;
}

.cli-content ol {
  margin-bottom: var(--space-6);
}

.cli-terminal {
  background-color: var(--bg-primary);
  border-radius: var(--radius-md);
  border: 1px solid var(--bg-tertiary);
  overflow: hidden;
}

.terminal-tabs {
  display: flex;
  border-bottom: 1px solid var(--bg-tertiary);
  background-color: rgba(0,0,0,0.2);
}

.terminal-tab {
  padding: var(--space-2) var(--space-4);
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  font-family: var(--font-mono);
  font-size: 0.875rem;
}

.terminal-tab.active {
  color: var(--brand-accent);
  border-bottom: 1px solid var(--brand-accent);
}

.terminal-code {
  padding: var(--space-4);
  font-family: var(--font-mono);
  color: var(--text-primary);
  overflow-x: auto;
  font-size: 0.9rem;
}

.terminal-code div {
  display: none;
}

.terminal-code div.active {
  display: block;
}

/* Footer */
.footer {
  border-top: 1px solid var(--bg-tertiary);
  padding: var(--space-12) 0 var(--space-6);
  margin-top: var(--space-16);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--space-8);
  margin-bottom: var(--space-8);
}

.footer-col h4 {
  font-size: 0.875rem;
  color: var(--text-primary);
  margin-bottom: var(--space-4);
}

.footer-col ul {
  list-style: none;
  padding: 0;
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-6);
  border-top: 1px solid var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 768px) {
  .hero h1 { font-size: 2.5rem; }
  .nav-links { display: none; }
  .sidebar { position: fixed; z-index: 50; background: var(--bg-primary); }
  .main-content { padding: var(--space-4); }
  .grid-3 { grid-template-columns: 1fr; }
}

document.addEventListener('DOMContentLoaded', () => {
  // Accordions for CLI Setup
  const accordionTabs = document.querySelectorAll('.accordion-tab');
  const cliContents = document.querySelectorAll('.cli-content');

  if (accordionTabs.length > 0) {
    accordionTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        // Remove active class from all
        accordionTabs.forEach(t => t.classList.remove('active'));
        cliContents.forEach(c => c.classList.remove('active'));

        // Add active class to clicked
        tab.classList.add('active');
        const target = tab.getAttribute('data-target');
        document.getElementById(target).classList.add('active');
      });
    });
  }

  // Terminal Package Manager Tabs
  const terminalTabs = document.querySelectorAll('.terminal-tab');
  const terminalCodes = document.querySelectorAll('.terminal-code div');

  if (terminalTabs.length > 0) {
    terminalTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        // Determine package manager clicked
        const pm = tab.getAttribute('data-pm');

        // Find parent terminal
        const terminal = tab.closest('.cli-terminal');
        const localTabs = terminal.querySelectorAll('.terminal-tab');
        const localCodes = terminal.querySelectorAll('.terminal-code div');

        // Update active tab in this terminal
        localTabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');

        // Update active code in this terminal
        localCodes.forEach(c => c.classList.remove('active'));
        terminal.querySelector(`div[data-pm="${pm}"]`).classList.add('active');

        // Sync across other terminals
        terminalTabs.forEach(globalTab => {
            if (globalTab.getAttribute('data-pm') === pm) {
                globalTab.classList.add('active');
                const globalTerminal = globalTab.closest('.cli-terminal');
                globalTerminal.querySelectorAll('.terminal-tab').forEach(gt => gt.classList.remove('active'));
                globalTab.classList.add('active');

                globalTerminal.querySelectorAll('.terminal-code div').forEach(gc => gc.classList.remove('active'));
                globalTerminal.querySelector(`div[data-pm="${pm}"]`).classList.add('active');
            }
        });
      });
    });
  }

  // Sidebar Toggle
  const sidebar = document.querySelector('.sidebar');
  const collapseBtn = document.querySelector('.collapse-btn');

  if (collapseBtn && sidebar) {
    collapseBtn.addEventListener('click', () => {
      sidebar.classList.toggle('collapsed');
      if (sidebar.classList.contains('collapsed')) {
        collapseBtn.innerHTML = '&#9776;'; // Hamburger
        collapseBtn.setAttribute('aria-expanded', 'false');
      } else {
        collapseBtn.innerHTML = '&times;'; // Close
        collapseBtn.setAttribute('aria-expanded', 'true');
      }
    });
  }

  // Dark Mode Toggle
  const themeToggle = document.querySelector('.theme-toggle');
  if (themeToggle) {
    themeToggle.addEventListener('click', () => {
      const html = document.documentElement;
      if (html.getAttribute('data-theme') === 'light') {
        html.removeAttribute('data-theme');
      } else {
        html.setAttribute('data-theme', 'light');
      }
    });
  }
});
